import {clamp,camera,mv} from './math.js';
import {basis1D,basis2D,gaussian1D,gaussian2D,sum1D,sum2D,target1D,target2D,fit1D,fit2D,error1D,error2D,sampleX} from './basis-math.js';

const number=x=>Math.abs(x)>100?x.toExponential(2):x.toFixed(3);
const colors=['#278fb8','#ba8643','#9273b0','#429c89','#b86b73','#6783b9'];
const slider=(id,label,min,max,step,value,unit='')=>`<label class="control"><span>${label}<output id="${id}-out">${number(value)}${unit}</output></span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}"></label>`;
const heading=(chapter,title,description,note)=>`<div class="module-heading"><div><p class="eyebrow">${chapter}</p><h2>${title}</h2><p class="description">${description}</p></div><aside class="model-note"><strong>What is being approximated?</strong>${note}</aside></div>`;
const metric=(name,id,detail)=>`<div class="metric"><span>${name}</span><strong id="${id}">—</strong><small>${detail}</small></div>`;
const graph=(id,label,w=720,h=340)=>`<div class="foundation-plot"><div class="visual-toolbar"><span>${label}</span></div><canvas id="${id}" width="${w}" height="${h}" aria-label="${label}"></canvas></div>`;
function axes(canvas,lo,hi){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,left=47,right=w-20,top=22,bottom=h-34;ctx.fillStyle='#f6faff';ctx.fillRect(0,0,w,h);ctx.font='11px ui-monospace, monospace';ctx.strokeStyle='#dbe7f0';ctx.fillStyle='#637f96';ctx.lineWidth=1;
  for(let i=0;i<=4;i++){const y=bottom-(bottom-top)*i/4;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.textAlign='right';ctx.fillText((lo+(hi-lo)*i/4).toFixed(1),left-8,y+4);}
  for(let x=-3;x<=3;x++){const px=left+(x+3)/6*(right-left);ctx.beginPath();ctx.moveTo(px,top);ctx.lineTo(px,bottom);ctx.stroke();ctx.textAlign='center';ctx.fillText(String(x),px,bottom+20);}ctx.textAlign='left';
  return {ctx,x:x=>left+(x+3)/6*(right-left),y:y=>bottom-(y-lo)/(hi-lo)*(bottom-top)};
}
function curve(a,fn,color,width=2,dash=[]){a.ctx.strokeStyle=color;a.ctx.lineWidth=width;a.ctx.setLineDash(dash);a.ctx.beginPath();sampleX.forEach((x,i)=>{const p=[a.x(x),a.y(fn(x))];i?a.ctx.lineTo(...p):a.ctx.moveTo(...p);});a.ctx.stroke();a.ctx.setLineDash([]);}

export class MixtureLab{
  constructor(){this.reset();}
  reset(){this.gs=basis1D(4);this.selected=0;this.kind='bumps';this.mode='Manual approximation';this.element=null;}
  unmount(){this.element=null;}
  q(s){return this.element.querySelector(s);}
  mount(element,next,gradient){this.element=element;this.next=next;
    element.innerHTML=heading('01 / APPROXIMATE A 1D FUNCTION','Build a function from Gaussian kernels.','Place a few soft bumps, add their weighted contributions, and compare the sum with a target function. Then let least squares choose the amplitudes.','A weighted function expansion. Coefficients can be signed and do not need to sum to one.')+
      `<div class="lab-layout"><aside class="controls"><div class="panel-heading"><h3>Your Gaussian basis</h3><button id="basis-reset" class="text-button">Reset ↺</button></div><label class="control"><span>Target function</span><select id="basis-target"><option value="bumps">Two smooth bumps</option><option value="detail">Plateau + sharp detail</option><option value="wave">Signed oscillation</option></select></label>${slider('basis-n','Number of Gaussians N',1,18,1,this.gs.length)}<label class="control"><span>Edit Gaussian</span><select id="basis-selected"></select></label>${slider('basis-mu','Mean μ',-3,3,.01,0)}${slider('basis-width','Width σ',.08,1.4,.01,.48)}${slider('basis-weight','Amplitude a',-2,2,.01,.25)}<div class="button-row"><button id="basis-fit" class="primary-button">Fit amplitudes · LSE</button><button id="basis-zero" class="small-button">Zero amplitudes</button></div><p class="control-note">LSE holds your means and widths fixed and solves all N amplitudes. Changing N starts a nested basis with width 0.48; then you can move and reshape each kernel.</p><div class="classification"><span id="basis-mode"></span><strong id="basis-rank"></strong><small id="basis-rank-note"></small></div></aside><div class="visual">${graph('basis-main','TARGET FUNCTION + CURRENT WEIGHTED SUM')}<div class="legend"><span><i class="dashed"></i>Target f(x)</span><span><i></i>Gaussian sum ŷ(x)</span></div><div class="foundation-pair">${graph('basis-components','INDIVIDUAL WEIGHTED GAUSSIANS',360,220)}${graph('basis-residual','RESIDUAL ŷ(x) − f(x)',360,220)}</div><div class="metrics">${metric('Current RMSE','basis-rmse','401 evenly spaced samples')}${metric('Squared error','basis-sse','Σ (ŷ − f)²')}${metric('Best RMSE with this basis','basis-best','Amplitudes chosen by LSE')}</div></div></div>
      <div class="formula-row"><div><span>One Gaussian kernel</span><code>φᵢ(x) = exp(−(x−μᵢ)²/(2σᵢ²))</code></div><div><span>Approximate the function</span><code>ŷ(x) = Σᵢ₌₁ᴺ aᵢ φᵢ(x)</code></div><div><span>Linear least-squares estimate</span><code>a* = argminₐ ‖Φa − y‖²</code></div></div>
      <section class="basis-capacity"><div><p class="eyebrow">WHAT DOES ADDING GAUSSIANS BUY US?</p><h3>Compare the best fit using the first 1, 2, …, N kernels.</h3><p>Each point solves a new least-squares problem using a prefix of your current basis. Additional basis functions can preserve the previous fit by receiving zero weight.</p></div><canvas id="basis-capacity" width="720" height="180" aria-label="Best least-squares RMSE using one through N of the current Gaussian kernels"></canvas></section>
      <details class="concept-details"><summary>Why is this least-squares problem linear?</summary><p>The matrix entry Φⱼᵢ is the value of Gaussian i at sample xⱼ. Once μᵢ and σᵢ are fixed, the prediction is linear in a. The QR solver finds amplitudes that minimize squared sample error. Moving means or changing widths is a different, nonlinear problem; that is introduced later when fitting a 3D scene. Very similar kernels can make the basis redundant or lead to large cancelling coefficients.</p></details><p class="experiment-note"><b>TRY THIS</b>Fit with N = 2, then N = 8. Switch to sharp detail. Can you improve the fit by moving one center toward the narrow peak?</p><div class="bottom-nav"><span>1D INPUT · 1D FUNCTION VALUE</span><button id="basis-next" class="text-button">Next: Extend the same idea to 2D →</button></div>`;
    this.q('#basis-reset').onclick=()=>{this.reset();this.mount(element,next,gradient);};this.q('#basis-next').onclick=next;
    this.q('#basis-target').onchange=e=>{this.kind=e.target.value;this.mode='Target changed · amplitudes unchanged';this.update();};
    this.q('#basis-n').oninput=e=>{this.gs=basis1D(Number(e.target.value));this.selected=Math.min(this.selected,this.gs.length-1);this.mode='New basis · place kernels or fit amplitudes';this.update();};
    this.q('#basis-selected').onchange=e=>{this.selected=Number(e.target.value);this.update();};
    for(const [id,key]of [['basis-mu','mu'],['basis-width','s'],['basis-weight','a']])this.q('#'+id).oninput=e=>{this.gs[this.selected][key]=Number(e.target.value);this.mode='Manual approximation';this.update();};
    this.q('#basis-fit').onclick=()=>{const fit=fit1D(this.gs,this.kind);this.gs.forEach((g,i)=>g.a=fit.weights[i]);this.mode='Least-squares amplitudes · μ and σ fixed';this.update();};
    this.q('#basis-zero').onclick=()=>{this.gs.forEach(g=>g.a=0);this.mode='Zero amplitudes · add one contribution at a time';this.update();};this.update();
  }
  update(){const g=this.gs[this.selected];this.q('#basis-selected').innerHTML=this.gs.map((_,i)=>`<option value="${i}">G${i+1}</option>`).join('');this.q('#basis-selected').value=this.selected;this.q('#basis-target').value=this.kind;this.q('#basis-n').value=this.gs.length;this.q('#basis-n-out').textContent=this.gs.length;
    for(const [id,key]of [['basis-mu','mu'],['basis-width','s'],['basis-weight','a']]){const input=this.q('#'+id);if(key==='a'){input.min=Math.min(-2,g.a*1.2);input.max=Math.max(2,g.a*1.2);}input.value=g[key];this.q('#'+id+'-out').textContent=number(g[key]);}
    const best=fit1D(this.gs,this.kind),error=error1D(this.gs,this.kind);this.q('#basis-mode').textContent=this.mode;this.q('#basis-rank').textContent=`Rank ${best.rank} / ${this.gs.length}`;this.q('#basis-rank-note').textContent=best.rank<this.gs.length?'Some kernels are redundant at the sample points.':'Independent basis columns at numerical precision.';this.q('#basis-rmse').textContent=number(error.rmse);this.q('#basis-sse').textContent=number(error.sse);this.q('#basis-best').textContent=number(Math.sqrt(best.sse/sampleX.length));
    const predicted=sampleX.map(x=>sum1D(x,this.gs)),target=sampleX.map(x=>target1D(x,this.kind)),lo=Math.min(-.15,...predicted,...target),hi=Math.max(1.1,...predicted,...target);let a=axes(this.q('#basis-main'),lo-.05,hi+.08);curve(a,x=>target1D(x,this.kind),'#b98442',2.6,[7,5]);curve(a,x=>sum1D(x,this.gs),'#258db7',2.8);
    const componentValues=this.gs.flatMap(g=>[g.a,0]);a=axes(this.q('#basis-components'),Math.min(-.1,...componentValues)-.05,Math.max(.5,...componentValues)+.05);this.gs.forEach((g,i)=>curve(a,x=>g.a*gaussian1D(x,g),colors[i%colors.length],i===this.selected?3:1.5));
    const maxError=Math.max(.05,...predicted.map((y,i)=>Math.abs(y-target[i])));a=axes(this.q('#basis-residual'),-maxError*1.1,maxError*1.1);curve(a,x=>sum1D(x,this.gs)-target1D(x,this.kind),'#8c71ac',2.3);
    const errors=this.gs.map((_,i)=>Math.sqrt(fit1D(this.gs.slice(0,i+1),this.kind).sse/sampleX.length));this.drawCapacity(errors);
  }
  drawCapacity(errors){const c=this.q('#basis-capacity'),ctx=c.getContext('2d');ctx.fillStyle='#f3f9fd';ctx.fillRect(0,0,720,180);const top=Math.max(.01,...errors);ctx.font='12px ui-monospace,monospace';ctx.fillStyle='#5d7b93';ctx.fillText('RMSE',12,20);ctx.fillText(number(top),12,43);ctx.fillText('0',24,145);ctx.strokeStyle='#d3e4ef';ctx.beginPath();ctx.moveTo(65,25);ctx.lineTo(65,140);ctx.lineTo(700,140);ctx.stroke();ctx.strokeStyle='#298fb7';ctx.lineWidth=2;ctx.beginPath();errors.forEach((e,i)=>{const x=70+i/Math.max(1,errors.length-1)*615,y=140-e/top*110;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();errors.forEach((e,i)=>{const x=70+i/Math.max(1,errors.length-1)*615,y=140-e/top*110;ctx.fillStyle='#258db7';ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#5d7b93';ctx.textAlign='center';ctx.fillText(String(i+1),x,163);});ctx.textAlign='left';}
}

function heatColor(v){if(v<0)return [100,83,150].map((x,i)=>Math.round(245+(x-245)*Math.min(1,-v)));const t=clamp(v/1.05,0,1);const a=t<.55?[245,249,253]:[76,167,184],b=t<.55?[76,167,184]:[222,160,75],u=t<.55?t/.55:(t-.55)/.45;return a.map((x,i)=>Math.round(x+(b[i]-x)*u));}
export class DimensionsLab{
  constructor(){this.reset();}
  reset(){this.gs=basis2D(4);this.selected=0;this.yaw=-36;this.pitch=28;this.mode='Manual 2D approximation';this.element=null;}
  unmount(){this.element=null;}
  q(s){return this.element.querySelector(s);}
  mount(element,next){this.element=element;
    element.innerHTML=heading('02 / EXTEND TO MORE DIMENSIONS','The same idea, with a vector input.','A Gaussian can cover a patch of a 2D function. Move its center, stretch its axes, rotate its covariance, and add its weighted contribution.','The domain is (x, y). Height in the surface plot shows the function value; it is not a third input coordinate.')+
      `<div class="dimension-bridge"><div><b>1D</b><span>μ ∈ ℝ · variance σ²</span><code>(x−μ)² / σ²</code></div><div class="active"><b>2D</b><span>μ ∈ ℝ² · covariance Σ ∈ ℝ²ˣ²</span><code>(x−μ)ᵀ Σ⁻¹ (x−μ)</code></div><div><b>3D next</b><span>μ ∈ ℝ³ · covariance Σ ∈ ℝ³ˣ³</span><code>Elliptical patch → ellipsoidal volume</code></div></div>
      <div class="lab-layout"><aside class="controls"><div class="panel-heading"><h3>2D Gaussian mixture</h3><button id="dims-reset" class="text-button">Reset ↺</button></div>${slider('dims-n','Number of Gaussians N',1,16,1,4)}<label class="control"><span>Edit Gaussian</span><select id="dims-selected"></select></label><div class="control-pair">${slider('dims-x','Mean x',-2,2,.01,-.8)}${slider('dims-y','Mean y',-2,2,.01,-.55)}</div><div class="control-pair">${slider('dims-sx','Scale σₓ',.08,1.2,.01,.5)}${slider('dims-sy','Scale σᵧ',.08,1.2,.01,.5)}</div>${slider('dims-angle','Rotation θ',-90,90,1,0,'°')}${slider('dims-weight','Amplitude a',-2,2,.01,.3)}<div class="button-row"><button id="dims-fit" class="primary-button">Fit 2D amplitudes · LSE</button><button id="dims-round" class="small-button">Make selected isotropic</button></div><p class="control-note">Click the approximation map to place the selected mean. Its contour shows one standard deviation. LSE solves the coefficients over a 31 × 31 sample grid.</p><p id="dims-mode" class="control-note"></p></aside><div class="visual"><div class="dimension-images">${graph('dims-target','TARGET FUNCTION f(x,y)',256,256)}${graph('dims-approx','GAUSSIAN SUM ŷ(x,y) · CLICK TO PLACE',256,256)}${graph('dims-error','ABSOLUTE ERROR · ×2',256,256)}</div><div class="surface-heading"><span>2D FUNCTION SHOWN AS A HEIGHT FIELD</span><span>Drag to inspect · height = scalar value</span></div><canvas id="dims-surface" width="720" height="330" tabindex="0" aria-label="The 2D Gaussian sum displayed as a 3D height field. Drag or use arrow keys to inspect; height is a scalar function value."></canvas><div class="metrics">${metric('Current 2D RMSE','dims-rmse','961 target samples')}${metric('Selected covariance Σ','dims-cov','Variances and cross-covariance')}${metric('Basis rank','dims-rank','Linear amplitudes with fixed shapes')}</div></div></div>
      <div class="formula-row"><div><span>A Gaussian in any dimension</span><code>φ(x) = exp(−½(x−μ)ᵀΣ⁻¹(x−μ))</code></div><div><span>Orient and stretch</span><code>Σ = R diag(σₓ², σᵧ²) Rᵀ</code></div><div><span>The fitting idea stays the same</span><code>ŷ(x,y) = Σᵢ aᵢ φᵢ(x,y); minₐ ‖Φa−y‖²</code></div></div><p class="experiment-note"><b>TRY THIS</b>Set N = 2. Place one elongated Gaussian on each target bump and rotate it to match. Fit amplitudes. Then add more kernels and compare the error.</p><details class="concept-details"><summary>What changes when the input becomes 3D?</summary><p>The mean gets a third coordinate, and covariance describes an ellipsoid with three principal axes. A 2D heatmap becomes a 3D scalar field, which we can inspect through level-set ellipsoids. In Gaussian Splatting, these 3D primitives carry appearance and opacity, are projected through a camera, and are alpha-composited into images. Next we fit a 3D scalar function directly; section 4 then adds appearance and camera rendering. An additive basis sum alone is not the 3DGS image formation model.</p></details><div class="bottom-nav"><span>SCALAR x → VECTOR (x,y) → VECTOR (x,y,z)</span><button id="dims-next" class="text-button">Next: Fit a 3D scalar function →</button></div>`;
    this.q('#dims-reset').onclick=()=>{this.reset();this.mount(element,next);};this.q('#dims-next').onclick=next;
    this.q('#dims-n').oninput=e=>{this.gs=basis2D(Number(e.target.value));this.selected=Math.min(this.selected,this.gs.length-1);this.mode='New 2D basis · edit shapes or fit amplitudes';this.update();};this.q('#dims-selected').onchange=e=>{this.selected=Number(e.target.value);this.update();};
    for(const [id,key]of [['dims-x','x'],['dims-y','y'],['dims-sx','sx'],['dims-sy','sy'],['dims-angle','angle'],['dims-weight','a']])this.q('#'+id).oninput=e=>{this.gs[this.selected][key]=Number(e.target.value);this.mode='Manual 2D approximation';this.update();};
    this.q('#dims-fit').onclick=()=>{const fit=fit2D(this.gs);this.gs.forEach((g,i)=>g.a=fit.weights[i]);this.mode='Least-squares amplitudes · means and covariances fixed';this.update();};this.q('#dims-round').onclick=()=>{const g=this.gs[this.selected];g.sx=g.sy=(g.sx+g.sy)/2;this.mode='Selected Gaussian is isotropic';this.update();};
    this.q('#dims-approx').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),g=this.gs[this.selected];g.x=clamp(-2+4*(e.clientX-r.x)/r.width,-2,2);g.y=clamp(2-4*(e.clientY-r.y)/r.height,-2,2);this.mode='Placed the selected mean';this.update();};
    let drag=null;const surface=this.q('#dims-surface');surface.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,yaw:this.yaw,pitch:this.pitch};surface.setPointerCapture(e.pointerId);};surface.onpointermove=e=>{if(!drag)return;this.yaw=drag.yaw+(e.clientX-drag.x)*.5;this.pitch=clamp(drag.pitch+(e.clientY-drag.y)*.3,10,65);this.drawSurface();};surface.onpointerup=()=>drag=null;surface.onpointercancel=()=>drag=null;surface.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();this.yaw+=({'ArrowLeft':-4,'ArrowRight':4}[e.key]||0);this.pitch=clamp(this.pitch+({'ArrowUp':-4,'ArrowDown':4}[e.key]||0),10,65);this.drawSurface();};this.update();
  }
  update(){const g=this.gs[this.selected];this.q('#dims-selected').innerHTML=this.gs.map((_,i)=>`<option value="${i}">G${i+1}</option>`).join('');this.q('#dims-selected').value=this.selected;this.q('#dims-n').value=this.gs.length;this.q('#dims-n-out').textContent=this.gs.length;
    for(const [id,key]of [['dims-x','x'],['dims-y','y'],['dims-sx','sx'],['dims-sy','sy'],['dims-angle','angle'],['dims-weight','a']]){const input=this.q('#'+id);if(key==='a'){input.min=Math.min(-2,g.a*1.2);input.max=Math.max(2,g.a*1.2);}input.value=g[key];this.q('#'+id+'-out').textContent=key==='angle'?g.angle.toFixed(0)+'°':number(g[key]);}
    const c=Math.cos(g.angle*Math.PI/180),s=Math.sin(g.angle*Math.PI/180),a=c*c*g.sx*g.sx+s*s*g.sy*g.sy,b=c*s*(g.sx*g.sx-g.sy*g.sy),d=s*s*g.sx*g.sx+c*c*g.sy*g.sy;
    this.q('#dims-cov').textContent=`[${a.toFixed(2)}, ${b.toFixed(2)}; ${b.toFixed(2)}, ${d.toFixed(2)}]`;this.q('#dims-rmse').textContent=number(error2D(this.gs));this.q('#dims-rank').textContent=`${fit2D(this.gs).rank} / ${this.gs.length}`;this.q('#dims-mode').textContent=this.mode;
    this.drawMap(this.q('#dims-target'),target2D);this.drawMap(this.q('#dims-approx'),(x,y)=>sum2D(x,y,this.gs),true);this.drawMap(this.q('#dims-error'),(x,y)=>2*Math.abs(sum2D(x,y,this.gs)-target2D(x,y)));this.drawSurface();
  }
  drawMap(canvas,fn,contours=false){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,image=ctx.createImageData(w,h);for(let j=0;j<h;j++)for(let i=0;i<w;i++){const v=fn(-2+4*i/(w-1),2-4*j/(h-1)),color=heatColor(v),offset=4*(j*w+i);image.data.set([...color,255],offset);}ctx.putImageData(image,0,0);
    if(contours)this.gs.forEach((g,i)=>{ctx.save();ctx.translate((g.x+2)/4*w,(2-g.y)/4*h);ctx.rotate(-g.angle*Math.PI/180);ctx.strokeStyle=i===this.selected?'#925e29':'#456c8790';ctx.lineWidth=i===this.selected?2:1;ctx.setLineDash(i===this.selected?[]:[4,4]);ctx.beginPath();ctx.ellipse(0,0,g.sx*w/4,g.sy*h/4,0,0,2*Math.PI);ctx.stroke();ctx.restore();if(i===this.selected){ctx.fillStyle='#fff';ctx.beginPath();ctx.arc((g.x+2)/4*w,(2-g.y)/4*h,3,0,Math.PI*2);ctx.fill();}});
  }
  drawSurface(){const canvas=this.q('#dims-surface'),ctx=canvas.getContext('2d');ctx.fillStyle='#f4f9fd';ctx.fillRect(0,0,720,330);const view=camera(this.yaw,this.pitch,10),map=(x,y,z)=>{const q=mv(view.r,[x,y,z]);return [360+q[0]*70,205+q[1]*70,q[2]];},n=30,points=[],samples=[];
    for(let j=0;j<=n;j++)for(let i=0;i<=n;i++){const x=-2+4*i/n,y=-2+4*j/n;samples.push({x,y,v:sum2D(x,y,this.gs)});}
    const verticalScale=1.7/Math.max(1,...samples.map(p=>Math.abs(p.v)));
    samples.forEach(({x,y,v})=>points.push({p:map(x,v*verticalScale,y),v}));
    ctx.strokeStyle='#d7e5ef';for(let i=-2;i<=2;i++){for(const ends of [[[i,0,-2],[i,0,2]],[[-2,0,i],[2,0,i]]]){ctx.beginPath();ctx.moveTo(...map(...ends[0]).slice(0,2));ctx.lineTo(...map(...ends[1]).slice(0,2));ctx.stroke();}}
    const faces=[];for(let j=0;j<n;j++)for(let i=0;i<n;i++){const a=j*(n+1)+i;for(const ids of [[a,a+1,a+n+2],[a,a+n+2,a+n+1]]){const ps=ids.map(k=>points[k]);faces.push({ps,depth:ps.reduce((s,p)=>s+p.p[2],0)/3,v:ps.reduce((s,p)=>s+p.v,0)/3});}}
    faces.sort((a,b)=>b.depth-a.depth).forEach(f=>{const col=heatColor(f.v);ctx.fillStyle=`rgb(${col.join(',')})`;ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=.6;ctx.beginPath();f.ps.forEach((p,i)=>i?ctx.lineTo(p.p[0],p.p[1]):ctx.moveTo(p.p[0],p.p[1]));ctx.closePath();ctx.fill();ctx.stroke();});ctx.fillStyle='#5a788f';ctx.font='12px ui-monospace,monospace';ctx.fillText('height = ŷ(x,y) · vertical scale adjusted to fit',16,24);ctx.fillText('map colors: negative = violet; 0 → 1.05+ = ivory → cyan → amber',16,311);ctx.fillText('x',...map(2.25,0,0).slice(0,2));ctx.fillText('y',...map(0,0,2.25).slice(0,2));
  }
}

export function mountHighResolution(element,back){
  const view='https://antimatter15.com/splat/?url=garden.splat';
  element.innerHTML=heading('07 / REAL GARDEN · GAUSSIAN SPLATTING','Now inspect a reconstruction at scene scale.','Explore the pretrained Garden capture: the same 3D means, covariances, opacity, projection, and compositing ideas, with around 5.8 million Gaussian primitives.','This viewer renders a pretrained Gaussian Splatting model. The preceding section trained a small NeRF-style neural field; the Garden returns to explicit Gaussian primitives.')+
    `<div class="highres-summary"><div><span>SCENE</span><strong>Garden</strong><small>Real outdoor capture · Mip-NeRF 360 scene</small></div><div><span>REPRESENTATION</span><strong>~5.8 million Gaussians</strong><small>Position · covariance · opacity · RGB</small></div><div><span>DELIVERY</span><strong>~187 MB streamed</strong><small>Public scene viewer · network + WebGL required</small></div></div><div class="highres-viewer visual"><div class="visual-toolbar"><span>CAPTURED SCENE / INTERACTIVE GAUSSIAN SPLATTING</span><a href="${view}" target="_blank" rel="noreferrer">Open original viewer ↗</a></div><div id="highres-stage"><div class="highres-placeholder"><div class="scene-wire-icon" aria-hidden="true">◌</div><p class="eyebrow">FROM A FEW KERNELS TO A CAPTURED ENVIRONMENT</p><h3>Load the real scene.</h3><p>The full model streams from the public viewer. Orbit around the garden, approach a surface, and examine fine structures and uncertain regions.</p><button id="highres-load" class="primary-button">Load Garden scene · ~187 MB</button></div></div><div class="highres-tools"><p id="highres-status" role="status">Ready to load · scene and viewer remain credited to their original providers.</p><button id="highres-fullscreen" class="small-button" disabled>Full screen ↗</button><button id="highres-reload" class="text-button" disabled>Reload viewer ↺</button></div></div><div class="highres-instructions"><p><b>Orbit:</b> drag with the left mouse button or one finger.</p><p><b>Move:</b> right-drag or use arrow keys; pinch on touch devices.</p><p><b>Inspect:</b> orbit slowly around leaves, thin branches, and the garden furniture.</p></div><div class="rationale-grid highres-observations"><article><b>Look for continuity</b><p>Move continuously through the garden. A single 3D representation continues to produce images as the camera changes.</p></article><article><b>Inspect fine detail</b><p>Approach edges, narrow structures, and broad surfaces. Relate them to the mixture size and anisotropic scales you explored earlier.</p></article><article><b>Find the limitations</b><p>Explore far from the captured region. Holes, floaters, or blurred regions reveal the limits of the available observations and representation.</p></article></div><div class="highres-credit"><p><b>Credits:</b> embedded viewer by <a href="https://github.com/antimatter15/splat" target="_blank" rel="noreferrer">Kevin Kwok / antimatter15</a>; Garden conversion hosted by <a href="https://huggingface.co/cakewalk/splat-data" target="_blank" rel="noreferrer">cakewalk / splat-data</a>; captured scene from <a href="https://jonbarron.info/mipnerf360/" target="_blank" rel="noreferrer">Mip-NeRF 360</a>; representation based on <a href="https://repo-sam.inria.fr/fungraph/3d-gaussian-splatting/" target="_blank" rel="noreferrer">Kerbl et al.</a> The viewer and model are streamed from their providers; they are not redistributed with this tutorial.</p><p>This compact web format stores RGB appearance. View-dependent spherical-harmonic appearance in full 3DGS is outside this viewer’s scope.</p></div><div class="bottom-nav"><button id="highres-back" class="text-button">← Return to the NeRF comparison</button><span>1D → 2D → 3D FIELD → COLOUR → RECONSTRUCTION → NeRF → GARDEN</span></div>`;
  const q=s=>element.querySelector(s);const load=()=>{q('#highres-stage').innerHTML=`<iframe id="highres-frame" title="Interactive real Garden Gaussian Splatting scene by Kevin Kwok" src="${view}" allow="fullscreen" allowfullscreen referrerpolicy="no-referrer"></iframe>`;q('#highres-status').textContent='Viewer opened · loading progress appears inside the scene. Click in the viewer to use its controls.';q('#highres-fullscreen').disabled=false;q('#highres-reload').disabled=false;};
  q('#highres-load').onclick=load;q('#highres-reload').onclick=load;q('#highres-fullscreen').onclick=()=>{q('#highres-frame').requestFullscreen?.().catch(()=>{q('#highres-status').textContent='Full screen is unavailable here; use Open original viewer to expand the scene.';});};q('#highres-back').onclick=back;
}
